mapper.select:
/* AppAdminApprovalMapper.selectPendingCorrOt */ SELECT R.REQ_ID AS reqId , R.REQ_TYPE AS reqType , R.USER_CD AS userCd , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'USER_NM', R.USER_CD, null) AS userNm , R.SITE_CD AS siteCd , R.NODE_CD AS nodeCd , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'NODE', R.SITE_CD, COALESCE(R.NODE_CD, U.NODE_CD)) AS nodeNm , R.WORK_YMD AS workYmd , R.WORK_SEQ AS workSeq , R.START_DATE AS startDate , R.START_TIME AS startTime , R.END_DATE AS endDate , R.END_TIME AS endTime , R.SCH_CD AS schCd
, RSE.FST_SCH_STR_TIME AS schFstStrTime , RSE.FST_SCH_END_TIME AS schFstEndTime , RSE.SEC_SCH_STR_TIME AS schSecStrTime , RSE.SEC_SCH_END_TIME AS schSecEndTime , R.REQ_REASON AS reqReason , DATE_FORMAT(R.INSERT_DATE, '%Y-%m-%dT%H:%i:%s') AS reqDate
, RSE.PRE_FIXED_OT_STR_TIME AS schPreFixedOtStrTime , RSE.PRE_FIXED_OT_END_TIME AS schPreFixedOtEndTime , RSE.FIXED_OT_STR_TIME AS schFixedOtStrTime , RSE.FIXED_OT_END_TIME AS schFixedOtEndTime FROM TB_USER_ATTD_REQ R LEFT JOIN TB_USER U ON U.CMPNY_CD = R.CMPNY_CD AND U.USER_CD = R.USER_CD
LEFT JOIN ( ) RSE ON RSE.CMPNY_CD = R.CMPNY_CD AND RSE.SITE_CD = R.SITE_CD AND RSE.SCH_CD = R.SCH_CD AND RSE.APPLY_DATE = ( SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= R.WORK_YMD THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( ) SE WHERE SE.CMPNY_CD = R.CMPNY_CD AND SE.SITE_CD = R.SITE_CD AND SE.SCH_CD = R.SCH_CD ) WHERE 1 = 1
ORDER BY R.INSERT_DATE DESC LIMIT #{limit} OFFSET #{offset}

